package cn.zhuatech.csm.controller; import cn.zhuatech.csm.common.ApiResponse; import cn.zhuatech.csm.dto.CsmDto.*; import cn.zhuatech.csm.service.CsmService; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/shopfloor") @PreAuthorize("hasAnyRole('SUCCESS_MANAGER','ADMIN')") public class SuccessManagerController {private final CsmService service;public SuccessManagerController(CsmService service){this.service=service;}@GetMapping("/dashboard") public ApiResponse<Dashboard> dashboard(){return ApiResponse.ok(service.shopfloorDashboard());}@PostMapping("/work-orders/{id}/reports") public ApiResponse<ReportResult> report(@PathVariable Long id,@Valid @RequestBody ReportRequest request){return ApiResponse.ok("反馈提交成功",service.report(id,request));}}
